record.field:
# ALTERNATIVES SYNC CODE:
review_alternatives = []
before = record.last_aternative_product_ids
now = record.alternative_product_ids

for i in before:
  if i not in now: review_alternatives.append(i)
for i in now:
  if i not in before: review_alternatives.append(i)

for p in review_alternatives:
  alternatives = env['product.template'].search([('alternative_product_ids','in',p.id)]).ids
  if (p.id not in now.ids) and (record.id in alternatives):
    alternatives.remove(record.id)
  if (p.id in now.ids) and (record.id not in alternatives):
    alternatives.append(record.id)
  if p.alternative_product_ids != alternatives:
      p.write({'alternative_product_ids':[(6,0,alternatives)]})


# ACCESORIES SYNC CODE:
review_accesories = []
before = record.last_accesory_product_ids
now = record.accesory_product_ids

for i in before:
  if i not in now: review_accesories.append(i)
for i in now:
  if i not in before: review_accesories.append(i)

for p in review_accesories:
  accesories = env['product.template'].search([('accesory_product_ids','in',p.id)]).ids
  if (p.id not in now.ids) and (record.id in accesories):
    accesories.remove(record.id)
  if (p.id in now.ids) and (record.id not in accesories):
    accesories.append(record.id)
#  if p.accesory_product_ids != accesories:
#      p.write({'accesory_product_ids':[(6,0,accesories)]})


# SINGLE RECORD WRITE:
record.write(
            {'last_aternative_product_ids':[(6,0,record.alternative_product_ids.ids)],
            'last_accesory_product_ids':[(6,0,record.accesory_product_ids.ids)],
            }
